mapper.select:
SELECT llm_value
FROM llm_parameter
WHERE llm_key = #{llmKey}

mapper.update:
UPDATE llm_parameter
SET llm_value = #{newValue}
WHERE llm_key = #{llmKey}
  AND llm_value = #{oldValue}

mapper.insert:
INSERT INTO llm_parameter (llm_key, llm_value)
SELECT #{llmKey}, #{llmValue}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM llm_parameter WHERE llm_key = #{llmKey}
)
